const html = $json.body || $json.data || '';

// --- 1) Convert HTML to clean text for reliable matching ---
const text = html
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

// --- 2) Strong NO-OFFERS detection (what the page shows when empty) ---
// If either phrase is present, we NEVER notify.
const noOffers =
  text.includes('keine angebote') ||
  text.includes('leider haben wir aktuell keine freien plätze') ||
  text.includes('schade - leider haben wir aktuell keine freien plätze');

// --- 3) Extract ONLY real offer detail links ---
// STRICT allow-list: links under /wohnen/aktuelle-wohnangebote/...
const hrefRegex = /href\s*=\s*"([^"]+)"/gi;
const found = new Set();
let m;

while ((m = hrefRegex.exec(html)) !== null) {
  let href = m[1];
  if (href.startsWith('/')) href = 'https://www.stwdo.de' + href;

  const isOfferDetail =
    href.startsWith('https://www.stwdo.de/wohnen/aktuelle-wohnangebote/') &&
    href !== 'https://www.stwdo.de/wohnen/aktuelle-wohnangebote/' &&
    href !== 'https://www.stwdo.de/wohnen/aktuelle-wohnangebote';

  if (isOfferDetail) found.add(href);
}

const offers = Array.from(found).sort();

// --- 4) Static memory (persists across runs) ---
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.prevOffers)) data.prevOffers = [];

// If page says NO offers: reset memory + output NO items (so Telegram won't run)
if (noOffers) {
  data.prevOffers = [];
  return [];
}

// Page does not say NO offers.
// Notify ONLY if we extracted real offer links and they are new.
const newOffers = offers.filter(u => !data.prevOffers.includes(u));

if (newOffers.length === 0) {
  // update memory anyway if offers exist (prevents repeated alerts)
  if (offers.length > 0) data.prevOffers = offers;
  return [];
}

// save current offers
if (offers.length > 0) data.prevOffers = offers;

// Output one item per new offer (Telegram nodes will send each)
return newOffers.map((url) => ({
  json: {
    offerUrl: url,
    message: `🏠 New STWDO dorm offer found!\n\n${url}\n\nMain page: https://www.stwdo.de/wohnen/aktuelle-wohnangebote`
  }
}));
